@Configuration
public class AppConfig {

    @Bean
    public MemberService memberService() {
        return new MemberServiceImpl(memberRepository());   // 호출 1
    }

    @Bean
    public OrderService orderService() {
        return new OrderServiceImpl(
                memberRepository(),                         // 호출 2
                discountPolicy());
    }

    @Bean
    public MemberRepository memberRepository() {
        return new MemoryMemberRepository();                // new 가 여기
    }
}

public class MemberServiceImpl implements MemberService {

    private final MemberRepository memberRepository;

    // 테스트 용도
    public MemberRepository getMemberRepository() {
        return memberRepository;
    }
}

@Test
void configurationTest() {
    ApplicationContext ac =
        new AnnotationConfigApplicationContext(AppConfig.class);

    MemberServiceImpl memberService = ac.getBean("memberService", MemberServiceImpl.class);
    OrderServiceImpl  orderService  = ac.getBean("orderService",  OrderServiceImpl.class);
    MemberRepository  memberRepository = ac.getBean("memberRepository", MemberRepository.class);

    MemberRepository repo1 = memberService.getMemberRepository();
    MemberRepository repo2 = orderService.getMemberRepository();

    System.out.println("memberService -> " + repo1);
    System.out.println("orderService  -> " + repo2);
    System.out.println("container     -> " + memberRepository);

    assertThat(repo1).isSameAs(memberRepository);
    assertThat(repo2).isSameAs(memberRepository);
}

@Configuration
public class AppConfig {

    @Bean
    public MemberService memberService() {
        System.out.println("call AppConfig.memberService");
        return new MemberServiceImpl(memberRepository());
    }

    @Bean
    public OrderService orderService() {
        System.out.println("call AppConfig.orderService");
        return new OrderServiceImpl(memberRepository(), discountPolicy());
    }

    @Bean
    public MemberRepository memberRepository() {
        System.out.println("call AppConfig.memberRepository");
        return new MemoryMemberRepository();
    }
}
